struct PageCache: AsyncMiddleware {
    let store: Cache                       // registered with app.caches.use(...)
    func respond(to req: Request, chainingTo next: Responder) async throws -> Response {
        let key = "page:\(req.method)\(req.url.string)"
        if let hit = try await store.get(key, as: Response.self).get() { return hit }
        let res = try await next.respond(to: req)          // origin path on a miss
        if res.status == .ok, req.method == .GET { try await store.set(key, to: res) }
        return res
    }
}
